// 依序處理：前導空白 → 正負號 → 數字，過程中檢查是否超出 32 位元範圍
// 時間複雜度: O(n)，空間複雜度: O(1)
function myAtoi(s) {
    const MAX = 2 ** 31 - 1, MIN = -(2 ** 31);
    let i = 0, sign = 1, result = 0;
    while (s[i] === ' ')
        i++;
    if (s[i] === '+' || s[i] === '-') {
        if (s[i] === '-')
            sign = -1;
        i++;
    }
    while (i < s.length && s[i] >= '0' && s[i] <= '9') {
        result = result * 10 + (s.charCodeAt(i) - 48);
        if (sign * result > MAX)
            return MAX; // 超過範圍立即截斷
        if (sign * result < MIN)
            return MIN;
        i++;
    }
    return sign * result || 0; // 避免回傳 -0
}

