class Solution {
public:
    int myAtoi(string s) {
        int i = 0, n = s.size();

        // 階段 1：跳過前置空格
        while (i < n && s[i] == ' ') i++;

        // 階段 2：處理正負號
        int sign = 1;
        if (i < n && (s[i] == '+' || s[i] == '-')) {
            sign = (s[i] == '-') ? -1 : 1;
            i++;
        }

        // 階段 3：讀數字，在運算前預判溢位
        int result = 0;
        while (i < n && isdigit(s[i])) {
            int digit = s[i] - '0';

            // 溢位檢查（在乘 10 之前！）
            if (result > INT_MAX / 10 ||
                (result == INT_MAX / 10 && digit > INT_MAX % 10)) {
                return (sign == 1) ? INT_MAX : INT_MIN;
            }

            result = result * 10 + digit;
            i++;
        }

        return sign * result;
    }
};

