// 依序處理：前導空白 → 正負號 → 數字，加下一位前先檢查是否溢位
// 時間複雜度: O(n)，空間複雜度: O(1)
int myAtoi(char* s) {
    int i = 0, sign = 1, result = 0;
    while (s[i] == ' ') i++;
    if (s[i] == '+' || s[i] == '-') {
        if (s[i] == '-') sign = -1;
        i++;
    }
    while (isdigit((unsigned char)s[i])) {
        int d = s[i] - '0';
        // result * 10 + d > INT_MAX 時溢位
        if (result > (INT_MAX - d) / 10) return sign == 1 ? INT_MAX : INT_MIN;
        result = result * 10 + d;
        i++;
    }
    return sign * result;
}

